class Solution:
    def reorderLogFiles(self, logs: list[str]) -> list[str]:
        def key(log: str):
            ident, rest = log.split(' ', 1)          # identifier, then the content
            if rest[0].isdigit():
                return (1,)                          # digit-logs: equal keys, stable sort keeps input order
            return (0, rest, ident)                  # letter-logs: content first, identifier breaks ties
        return sorted(logs, key=key)                 # N log N comparisons, each up to M characters
